<template>
  <q-dialog :model-value="modelValue" persistent @update:model-value="$emit('update:modelValue',$event)">
    <q-card class="count-dialog">
      <q-toolbar class="count-toolbar"><div class="header-icon"><q-icon name="inventory" size="27px" /></div><q-toolbar-title><div class="toolbar-title">Conteo físico <span>{{ inventario?.codigo }}</span></div><div class="toolbar-sub">{{ inventario?.almacen }} · Registra las cantidades encontradas</div></q-toolbar-title><q-badge class="status-badge" color="orange-8" label="EN CONTEO" /><q-btn class="close-btn q-ml-md" flat round dense icon="close" aria-label="Cerrar" @click="$emit('update:modelValue',false)"><q-tooltip>Cerrar</q-tooltip></q-btn></q-toolbar>
      <div class="count-container">
        <div class="row q-col-gutter-md q-mb-lg">
          <div class="col-12 col-md-8"><q-card flat bordered class="info-card"><q-card-section class="row items-center"><div class="col"><div class="small-label">Avance del conteo</div><div class="progress-title">{{ resumen.contados }} de {{ resumen.total }} registros contados</div><div class="small-label">{{ resumen.pendientes }} pendientes</div></div><div class="progress-number">{{ resumen.porcentajeAvance }}%</div></q-card-section><q-linear-progress :value="resumen.porcentajeAvance/100" color="green-8" track-color="green-1" size="9px" /></q-card></div>
          <div class="col-12 col-md-4"><q-card flat bordered class="info-card"><q-card-section><div class="small-label">Responsable</div><b>{{ inventario?.responsable }}</b><div class="small-label q-mt-xs">Último guardado: {{ ultimoGuardado }}</div></q-card-section></q-card></div>
        </div>
        <q-card flat bordered class="tool-card q-mb-lg"><q-card-section><div class="tools-title"><q-icon name="manage_search" color="green-8" /> Buscar y filtrar productos</div><div class="row q-col-gutter-md items-center"><div class="col-12 col-md-7"><q-input v-model="buscar" outlined dense clearable debounce="350" label="Escanear código o buscar producto" autofocus @update:model-value="aplicarFiltros"><template #prepend><q-icon name="qr_code_scanner" color="green-8" /></template></q-input></div><div class="col-12 col-sm-6 col-md"><div class="toggle-box"><q-toggle v-model="soloPendientes" color="green-8" label="Solo pendientes" @update:model-value="aplicarFiltros" /></div></div><div class="col-12 col-sm-6 col-md"><div class="toggle-box warning"><q-toggle v-model="soloDiferencias" color="orange-8" label="Con diferencias" :disable="inventario?.ciego" @update:model-value="aplicarFiltros"><q-tooltip v-if="inventario?.ciego">Disponible al finalizar el conteo ciego</q-tooltip></q-toggle></div></div></div></q-card-section></q-card>
        <q-card flat bordered class="table-card"><q-table v-model:pagination="pagination" :rows="productos" :columns="columns" row-key="id" flat :loading="cargando" :rows-per-page-options="[10,20,50]" rows-per-page-label="Registros por página" @request="cargar">
          <template #body-cell-producto="p"><q-td :props="p"><div class="product-name">{{ p.row.producto }}</div><div class="product-code">{{ p.row.codigo }} · {{ p.row.unidad }}</div></q-td></template>
          <template #body-cell-ubicacion="p"><q-td :props="p"><div>{{ p.row.ubicacion }}</div><div class="product-code">{{ p.row.almacen }} · Lote: {{ p.row.lote || '--' }}</div></q-td></template>
          <template #body-cell-sistema="p"><q-td :props="p"><span v-if="!inventario?.ciego">{{ numero(p.row.sistema) }}</span><q-icon v-else name="visibility_off" color="grey-5"><q-tooltip>Conteo ciego</q-tooltip></q-icon></q-td></template>
          <template #body-cell-fisico="p"><q-td :props="p"><q-input v-model.number="p.row.fisico" outlined dense type="number" min="0" class="quantity-input" @update:model-value="marcar(p.row)" /></q-td></template>
          <template #body-cell-diferencia="p"><q-td :props="p"><q-badge v-if="p.row.fisico!==null&&!inventario?.ciego" :color="diferencia(p.row)===0?'green-7':diferencia(p.row)<0?'red-6':'blue-6'" :label="formatoDiferencia(p.row)"/><span v-else>--</span></q-td></template>
          <template #body-cell-estado="p"><q-td :props="p"><q-icon :name="p.row.fisico===null?'radio_button_unchecked':'check_circle'" :color="p.row.fisico===null?'grey-5':'green-7'" size="21px" /></q-td></template>
        </q-table></q-card>
      </div>
      <div class="sticky-actions"><div class="text-caption text-grey-7">Los cambios se conservan al guardar el borrador.</div><div class="row q-gutter-sm"><q-btn v-permiso="'INVENTARIO_FISICO_EDITAR'" outline no-caps color="green-8" icon="save" label="Guardar borrador" :loading="cargando" @click="guardar()"/><q-btn v-permiso="'INVENTARIO_FISICO_APROBAR'" unelevated no-caps color="green-8" icon="task_alt" label="Finalizar conteo" :loading="finalizando" @click="prepararFinalizacion"/></div></div>
      <q-dialog v-model="confirmar" persistent><q-card class="confirm-card"><q-card-section class="text-center q-pa-lg"><q-icon name="fact_check" color="green-8" size="54px"/><div class="confirm-title">¿Finalizar el conteo?</div><p class="text-grey-7">Las cantidades dejarán de editarse y el inventario pasará a revisión.</p><div class="confirm-summary" :class="{'two-columns':inventario?.ciego}"><div><span>Total</span><b>{{ resumen.total }}</b></div><div><span>Contados</span><b class="text-green-8">{{ resumen.contados }}</b></div><div v-if="!inventario?.ciego"><span>Diferencias</span><b class="text-orange-9">{{ resumen.diferencias }}</b></div></div><div v-if="inventario?.ciego" class="blind-note"><q-icon name="visibility_off" /> Las diferencias se mostrarán en la revisión.</div></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Volver" :disable="finalizando" v-close-popup/><q-btn unelevated no-caps color="green-8" label="Sí, finalizar" :loading="finalizando" @click="finalizar"/></q-card-actions></q-card></q-dialog>
    </q-card>
  </q-dialog>
</template>
<script setup>
import { reactive, ref, watch } from 'vue';import { useQuasar } from 'quasar';import { finalizarConteoFisico, guardarAvanceConteoFisico, listarDetallesConteoFisico } from '../../api/inventarioFisico/inventarioFisico'
const props=defineProps({modelValue:Boolean,inventario:Object});const emit=defineEmits(['update:modelValue','guardar','finalizar']);const $q=useQuasar();const buscar=ref('');const soloPendientes=ref(false);const soloDiferencias=ref(false);const confirmar=ref(false);const ultimoGuardado=ref('Sin guardar');const cargando=ref(false);const finalizando=ref(false);const productos=ref([]);const borradores=new Map();const resumen=reactive({total:0,contados:0,pendientes:0,diferencias:0,porcentajeAvance:0,ultimoGuardado:null});const pagination=ref({page:1,rowsPerPage:10,rowsNumber:0,sortBy:'producto',descending:false})
const columns=[{name:'producto',label:'Producto',field:'producto',align:'left'},{name:'ubicacion',label:'Ubicación',field:'ubicacion',align:'left'},{name:'sistema',label:'Stock sistema',field:'sistema',align:'center'},{name:'fisico',label:'Cantidad física',field:'fisico',align:'center'},{name:'diferencia',label:'Diferencia',align:'center'},{name:'estado',label:'Contado',align:'center'}]
const diferencia=r=>Number(r.fisico)-Number(r.sistema);const formatoDiferencia=r=>`${diferencia(r)>0?'+':''}${numero(diferencia(r))}`;const numero=v=>v===null||v===undefined?'--':Number(v).toLocaleString('es-BO',{maximumFractionDigits:3})
function mapear(x){const borrador=borradores.get(x.idDetalle);return{id:x.idDetalle,codigo:x.codigoProducto||'S/C',producto:x.producto,unidad:x.unidad||'--',almacen:x.almacen,ubicacion:x.ubicacion,lote:x.lote,fechaVencimiento:x.fechaVencimiento,sistema:x.cantidadSistema,fisico:borrador!==undefined?borrador:x.cantidadFisica,contado:x.contado}}
async function cargar(ctx){if(!props.inventario?.id)return;const p=ctx?.pagination||pagination.value;pagination.value={...pagination.value,...p};cargando.value=true;try{const r=await listarDetallesConteoFisico(props.inventario.id,{buscar:buscar.value||undefined,soloPendientes:soloPendientes.value||undefined,soloDiferencias:soloDiferencias.value||undefined,page:p.page-1,size:p.rowsPerPage,sortBy:p.sortBy||'producto',sortDir:p.descending?'desc':'asc'});productos.value=(r?.detalles?.content||[]).map(mapear);pagination.value.rowsNumber=Number(r?.detalles?.totalElements||0);Object.assign(resumen,r?.resumen||{});ultimoGuardado.value=formatearHora(resumen.ultimoGuardado)}catch(e){productos.value=[];$q.notify({type:'negative',message:e?.response?.data?.message||'No se pudo cargar el conteo.'})}finally{cargando.value=false}}
function aplicarFiltros(){pagination.value.page=1;cargar()}function marcar(row){if(row.fisico===null||row.fisico===''){borradores.delete(row.id);return}borradores.set(row.id,row.fisico)}
async function guardar(mostrarMensaje=true){if(!borradores.size){if(mostrarMensaje)$q.notify({type:'info',message:'No existen cambios para guardar.'});return true}const detalles=[...borradores.entries()].map(([idDetalle,cantidadFisica])=>({idDetalle,cantidadFisica,observacion:null}));if(detalles.some(x=>!Number.isFinite(Number(x.cantidadFisica))||Number(x.cantidadFisica)<0||!/^\d+(\.\d{1,3})?$/.test(String(x.cantidadFisica)))){$q.notify({type:'warning',message:'Las cantidades deben ser cero o mayores y tener máximo 3 decimales.'});return false}cargando.value=true;try{const r=await guardarAvanceConteoFisico(props.inventario.id,{detalles});borradores.clear();Object.assign(resumen,r||{});ultimoGuardado.value=formatearHora(resumen.ultimoGuardado);if(mostrarMensaje)$q.notify({type:'positive',message:'Avance del conteo guardado correctamente.'});emit('guardar',r);await cargar();return true}catch(e){$q.notify({type:'negative',message:e?.response?.data?.message||'No se pudo guardar el avance.'});return false}finally{cargando.value=false}}
async function prepararFinalizacion(){const guardado=await guardar(false);if(!guardado)return;if(resumen.pendientes>0){soloPendientes.value=true;aplicarFiltros();return $q.notify({type:'warning',message:`Faltan ${resumen.pendientes} registros por contar.`})}confirmar.value=true}
async function finalizar(){finalizando.value=true;try{const r=await finalizarConteoFisico(props.inventario.id);confirmar.value=false;$q.notify({type:'positive',message:'Conteo finalizado y enviado a revisión.'});emit('finalizar',r);emit('update:modelValue',false)}catch(e){$q.notify({type:'negative',message:e?.response?.data?.message||'No se pudo finalizar el conteo.'})}finally{finalizando.value=false}}function formatearHora(v){return v?new Date(v).toLocaleString('es-BO'):'Sin guardar'}watch(()=>props.modelValue,v=>{if(v){buscar.value='';soloPendientes.value=false;soloDiferencias.value=false;borradores.clear();pagination.value.page=1;cargar()}})
</script>
<style scoped>
.count-dialog{width:min(1450px,96vw);max-width:1450px;height:min(900px,94vh);display:flex;flex-direction:column;overflow:hidden;border-radius:18px;background:#f5f7f4;color:#263238;font-family:'Nunito',sans-serif;box-shadow:0 18px 55px rgba(30,63,21,.2)}.count-toolbar{min-height:78px;padding:0 22px;background:linear-gradient(135deg,#f1f9ec 0%,#fff 72%);border-bottom:1px solid #d8e5d3}.header-icon{width:48px;height:48px;border-radius:14px;display:grid;place-items:center;color:#fff;background:linear-gradient(135deg,#82bd43,#4a8c25);box-shadow:0 5px 14px rgba(74,140,37,.22)}.toolbar-title{font-size:20px;font-weight:900;color:#243323}.toolbar-title span{margin-left:6px;color:#4a8c25}.toolbar-sub{font-size:12px;color:#778077;font-weight:400;margin-top:2px}.status-badge{padding:6px 10px;font-weight:800;letter-spacing:.3px}.close-btn{color:#657066;background:#fff;border:1px solid #dbe5d7}.close-btn:hover{color:#b42318;background:#fff5f4}.count-container{width:100%;max-width:1450px;margin:auto;padding:22px;overflow:auto;flex:1}.info-card,.tool-card,.table-card{border-radius:15px;border-color:#dfe7dc;box-shadow:0 3px 13px rgba(62,96,52,.05)}.info-card{overflow:hidden;background:#fff}.small-label{font-size:11px;color:#778077}.progress-title{font-size:17px;font-weight:900}.progress-number{font-size:26px;font-weight:900;color:#4a8c25}.tools-title{display:flex;align-items:center;gap:7px;margin-bottom:13px;font-size:13px;font-weight:900;color:#3c503b}.toggle-box{min-height:40px;padding:0 9px;border:1px solid #dce8d7;border-radius:9px;background:#f6fbf3;display:flex;align-items:center}.toggle-box.warning{border-color:#f0dfbd;background:#fffaf0}.table-card{overflow:hidden}:deep(.q-table thead tr){background:#f0f8e9}:deep(.q-table th){font-weight:900;color:#3f5140}.product-name{font-weight:800}.product-code{font-size:11px;color:#7b857c}.quantity-input{width:110px;margin:auto}.sticky-actions{flex:none;background:#fff;border-top:1px solid #dfe7dc;padding:14px 22px;display:flex;justify-content:space-between;align-items:center;z-index:2;box-shadow:0 -5px 18px rgba(45,73,38,.06)}.confirm-card{width:min(460px,94vw);border-radius:18px}.confirm-title{font-size:20px;font-weight:900;margin-top:10px}.confirm-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:18px}.confirm-summary.two-columns{grid-template-columns:repeat(2,1fr)}.confirm-summary div{padding:11px 7px;border-radius:10px;background:#f5f8f3;display:flex;flex-direction:column}.confirm-summary span{font-size:11px;color:#778077}.confirm-summary b{font-size:18px}.blind-note{margin-top:12px;padding:9px;border-radius:9px;background:#f3f4f6;color:#68706a;font-size:12px}@media(max-width:650px){.count-dialog{width:100vw;height:100vh;max-height:100vh;border-radius:0}.count-toolbar{padding:0 12px}.header-icon{width:42px;height:42px}.toolbar-title{font-size:16px}.status-badge{display:none}.sticky-actions{align-items:stretch;gap:8px;flex-direction:column}.sticky-actions .row{width:100%}.sticky-actions .q-btn{flex:1}.count-container{padding:14px}}
</style>
